def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay keys and values over defaults mode=fast and level=3."""
    pre keys.len() == values.len()
    ex settings(keys=[], values=[]) == ["fast", "3"]
    ex settings(keys=["mode"], values=["safe"]) == ["safe", "3"]
    ex settings(keys=["extra", "level"], values=["val", "1"]) == ["fast", "1", "val"]
    mode = "fast"
    level = "3"
    extra_order: list[str] = []
    extras: dict[str, str] = {}
    for i in range(keys.len()):
        k = keys[i]
        v = values[i]
        if k == "mode":
            mode = v.copy()
        elif k == "level":
            level = v.copy()
        else:
            if k not in extras:
                extra_order.append(k.copy())
            extras[k] = v.copy()
    out: list[str] = [mode, level]
    for k in extra_order:
        val = extras.get(k) else ""
        out.append(val.copy())
    return out

